// One JSON snapshot per line from pylontech_live.py -> widget (1), status text (2).
var data = msg.payload;
if (!data || typeof data !== 'object') { return null; }
if (!data.ok || !data.modules || !data.modules.length) {
    return [null, { topic: 'status', payload: 'Error: ' + (data.error || 'no data') }];
}
data.updated = new Date().toLocaleTimeString('cs-CZ');
var status = null;
if (data.live && context.get('wasLive') !== true) {
    status = { topic: 'status', payload: 'Live running – the whole stack incl. cells updates every 8 s' };
}
context.set('wasLive', data.live === true);
msg.payload = data;
return [msg, status];

// One owner of the battery port at a time: Live (pylontech_live.py) or a log export
// (pylontech_export.py). Inputs (msg.topic): 'live' (payload true/false), 'export' (payload
// 'connected' | 'stack'), 'export_cancel', 'live_rc' / 'export_rc' (a process ended).
// Outputs: 1 live exec, 2 export exec, 3 UI state (one or more {topic, payload}).
// Live button states: idle | live | stopping | export.
const mode = context.get('mode') || 'idle';          // idle | live | export
const ui = (topic, payload) => ({ topic: topic, payload: payload });
const status = (t) => ui('status', t);
const panel = (o) => ui('export', Object.assign({ mode: flow.get('export_mode') || 'stack',
    last: flow.get('last_export') || null, recent: flow.get('recent_exports') || [] }, o));
const startExport = (kind) => {
    context.set('mode', 'export');
    flow.set('export_mode', kind);
    return [null, { payload: kind === 'connected' ? '--connected' : '' },
            [ui('live', 'export'),
             status(kind === 'connected' ? 'Reading the connected module…' : 'Exporting the whole stack…'),
             panel({ state: 'running', step: 'start' })]];
};

switch (msg.topic) {
case 'live':
    if (msg.payload === true) {
        if (mode === 'export') return [null, null, [status('Log export running – Live cannot be started now'), ui('live', 'export')]];
        if (mode === 'live') return [null, null, [status('Live is already running'), ui('live', 'live')]];
        context.set('mode', 'live');
        context.set('wanted', true);
        return [{ payload: '' }, null, [status('Starting Live…'), ui('live', 'live')]];
    }
    if (mode === 'live') {
        context.set('wanted', false);
        return [{ kill: 'SIGTERM' }, null, [status('Stopping Live…'), ui('live', 'stopping')]];
    }
    return null;

case 'export': {
    const kind = msg.payload === 'connected' ? 'connected' : 'stack';
    if (mode === 'export') return [null, null, [status('A log export is already running')]];
    if (mode === 'live') {
        context.set('pendingExport', kind);
        context.set('wanted', false);
        return [{ kill: 'SIGTERM' }, null, [status('Stopping Live and starting the log export…'), ui('live', 'export')]];
    }
    return startExport(kind);
}

case 'export_cancel':
    if (mode === 'export') return [null, { kill: 'SIGTERM' }, [status('Cancelling the log export…')]];
    context.set('pendingExport', null);
    return [null, null, [status('No log export running')]];

case 'live_rc': {
    if (mode !== 'live') return null;
    context.set('mode', 'idle');
    const pending = context.get('pendingExport');
    if (pending) {
        context.set('pendingExport', null);
        return startExport(pending);
    }
    const wanted = context.get('wanted') === true;
    context.set('wanted', false);
    if (!wanted) return [null, null, [status('Live stopped'), ui('live', 'idle')]];
    const code = msg.payload && msg.payload.code;
    const why = {
        0: 'Live stopped itself after 30 minutes',
        2: 'Live cannot start: the port is busy or the battery does not answer',
        3: 'Live stopped: communication error with the battery',
    }[code] || ('Live ended (code ' + code + ')');
    return [null, null, [status(why), ui('live', 'idle')]];
}

case 'export_rc': {
    if (mode !== 'export') return null;
    context.set('mode', 'idle');
    const code = msg.payload && msg.payload.code;
    if (code === 0) return [null, null, [ui('live', 'idle')]];      // the "done" line already updated the panel
    const why = {
        2: 'Log export cannot start: the port is busy or the battery does not answer',
        3: 'Log export stopped: communication error with the battery',
        4: 'Log export cancelled',
    }[code] || ('Log export failed (code ' + code + ')');
    return [null, null, [status(why), ui('live', 'idle'), panel({ state: 'error', error: why })]];
}
}
return null;

initialize:
// After a deploy or restart nothing runs (exec nodes kill their processes on redeploy).
context.set('mode', 'idle');
context.set('wanted', false);
context.set('pendingExport', null);

