// JSON lines from pylontech_export.py -> UI state (export panel, status text).
var d = msg.payload;
if (!d || typeof d !== 'object') { return null; }
var mode = flow.get('export_mode') || 'stack';
var last = flow.get('last_export') || null;          // last whole-stack export
var recent = flow.get('recent_exports') || [];       // single-module exports, newest first
var ctx = { mode: mode, last: last, recent: recent };
if (d.type === 'progress') {
    return [{ topic: 'export', payload: Object.assign({}, d, ctx, { state: 'running' }) }, null];
}
if (d.type === 'done') {
    var rec = { name: d.name, size: d.size, duration_s: d.duration_s, retries: d.retries, mode: d.mode,
                modules: d.modules, at: new Date().toLocaleString('en-GB') };
    if (d.mode === 'connected') {
        recent = [rec].concat(recent.filter(function (r) { return r.name !== rec.name; })).slice(0, 20);
        flow.set('recent_exports', recent);
    } else {
        last = rec;
        flow.set('last_export', last);
    }
    var m = d.modules && d.modules[0];
    var text = d.mode === 'connected' && m
        ? 'Module M' + m.module + ' (' + m.barcode + ') exported – move the cable to the next module'
        : 'Whole stack exported';
    return [{ topic: 'export', payload: { state: 'done', mode: mode, last: last, recent: recent } },
            { topic: 'status', payload: text }];
}
if (d.type === 'error') {
    return [{ topic: 'export', payload: Object.assign(ctx, { state: 'error', error: d.error }) }, null];
}
return null;

// GET /pylontech/exports/<name>: only our ZIP files, nothing else from the disk.
var name = (msg.req && msg.req.params && msg.req.params.name) || '';
if (!/^pylontech_(logs|module)_[0-9A-Za-z_-]+\.zip$/.test(name)) {
    msg.statusCode = 404;
    msg.payload = 'not found';
    return [null, msg];
}
msg.filename = '/data/pylontech/exports/' + name;
return [msg, null];

if (msg.error || !Buffer.isBuffer(msg.payload)) {
    msg.statusCode = 404;
    msg.payload = 'not found';
    return msg;
}
msg.statusCode = 200;
msg.headers = {
    'Content-Type': 'application/zip',
    'Content-Disposition': 'attachment; filename="' + msg.req.params.name + '"'
};
return msg;

// Merges partial UI updates into one state for the header and the export card.
// msg.topic: 'live' (idle|live|stopping|export), 'status' (text), 'export' (export panel).
var ui = context.get('ui') || { live: 'idle', status: '', export: { state: 'idle' } };
if (msg.topic === 'live') ui.live = msg.payload;
else if (msg.topic === 'status') ui.status = msg.payload;
else if (msg.topic === 'export') ui.export = msg.payload;
else return null;
context.set('ui', ui);
return { payload: ui };

// After a deploy / restart nothing runs: Live off, the export history from flow context.
return [
    { topic: 'live', payload: 'idle' },
    { topic: 'export', payload: { state: 'idle', last: flow.get('last_export') || null,
                                  recent: flow.get('recent_exports') || [] } }
];

