/* Dark look for the Pylontech page only; the shared dashboard theme and other pages stay as they are. */
.v-theme--nrdb, .v-application, :root {
  --v-theme-background: 11,14,19 !important;
  --v-theme-on-background: 229,231,235 !important;
  --v-theme-surface: 11,14,19 !important;
  --v-theme-on-surface: 229,231,235 !important;
  --v-theme-group-background: 11,14,19 !important;
  --v-theme-on-group-background: 229,231,235 !important;
  --v-theme-group-outline: 11,14,19 !important;
  --v-theme-navigation-background: 15,19,24 !important;
  --v-theme-on-navigation-background: 229,231,235 !important;
  --nrdb-bg-color: #0b0e13 !important;
  --nrdb-text-color: #e5e7eb !important;
}
html, body, .v-application, .v-main { background: #0b0e13 !important; }
.v-app-bar.v-toolbar { background: #0f1318 !important; color: #e5e7eb !important; border-bottom: 1px solid #1c232c !important; box-shadow: none !important; }
.v-app-bar .v-toolbar-title { font-weight: 600; letter-spacing: .02em; }
.v-navigation-drawer { background: #0f1318 !important; color: #e5e7eb !important; border-color: #1c232c !important; }
.nrdb-layout--grid { max-width: 1440px; margin: 0 auto; }
.nrdb-ui-group { grid-column: 1 / -1 !important; }
.nrdb-ui-group > .v-card { background: transparent !important; border: 0 !important; box-shadow: none !important; }
